from fractions import Fraction

def power(p, a, b):
    return (b**(p + 1) - a**(p + 1)) / (p + 1)

def polynomial_integral(coeffs, a, b):
    total = 0
    for p in range(len(coeffs)):
        total = total + coeffs[p] * power(p, a, b)
    print(f"integral = {total}")

k = int(input())
for i in range(k):
    # input().split() cuts a line at its spaces into a list of words
    nums = [Fraction(w) for w in input().split()]
    a, b = nums[0], nums[1]
    polynomial_integral(nums[2:], a, b)

