import math

def bounds(f, a, b, n):
    dx = (b - a) / n
    lower, upper = 0, 0
    for i in range(n):
        left, right = f(a + i*dx), f(a + (i + 1)*dx)
        if left < right:
            lower, upper = lower + left*dx, upper + right*dx
        else:
            lower, upper = lower + right*dx, upper + left*dx
    return lower, upper

def report(label, f, a, b):
    print(label)
    for n in [1, 2, 10, 100]:
        lower, upper = bounds(f, a, b, n)
        print(f"  n = {n}: {lower:.6f} <= integral <= {upper:.6f}, width {upper - lower:.6f}")

report("Example 1 · sqrt(1 + x^3) on [0, 1], increasing", lambda x: math.sqrt(1 + x**3), 0, 1)
report("Example 2 · e^(-x^2) on [0, 1], decreasing", lambda x: math.exp(-x**2), 0, 1)
report("Your turn 1 · 1/x on [1, 2], decreasing", lambda x: 1 / x, 1, 2)

